#[derive(Clone, Debug, Eq, PartialEq)]
enum ProjectedBlockItemV1 {
    Effect {
        operation: ProductionRankedOperationV1,
        source: Option<ProjectedEffectSourceV1>,
    },
    Guarded(GuardedRankedAccessV1),
    Pipeline(ProjectedPipelineEffectV1),
    GeneratedFromSemanticTerminator(ProjectedGeneratedExecutableEffectV1),
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct ProjectedSemanticBlockV1 {
    items: Vec<ProjectedBlockItemV1>,
}

impl ProjectedSemanticBlockV1 {
    fn has_memory_access(&self) -> bool {
        self.items.iter().any(|item| match item {
            ProjectedBlockItemV1::Effect {
                operation:
                    ProductionRankedOperationV1::Access { .. }
                    | ProductionRankedOperationV1::AtomicAccess { .. }
                    | ProductionRankedOperationV1::AllocationEffect { .. },
                ..
            }
            | ProjectedBlockItemV1::Guarded(_) => true,
            ProjectedBlockItemV1::Pipeline(ProjectedPipelineEffectV1::Access { .. }) => true,
            ProjectedBlockItemV1::Pipeline(_) => false,
            ProjectedBlockItemV1::GeneratedFromSemanticTerminator(effect) => {
                matches!(
                    &effect.operation,
                    ProductionRankedOperationV1::Access { .. }
                        | ProductionRankedOperationV1::AtomicAccess { .. }
                        | ProductionRankedOperationV1::AllocationEffect { .. }
                )
            }
            ProjectedBlockItemV1::Effect { .. } => false,
        })
    }

    fn requires_invocation_index(&self) -> bool {
        self.items.iter().any(|item| match item {
            ProjectedBlockItemV1::Effect {
                operation:
                    ProductionRankedOperationV1::AtomicAccess { .. }
                    | ProductionRankedOperationV1::AtomicValueAccess { .. },
                ..
            } => false,
            ProjectedBlockItemV1::Effect {
                source: Some(source),
                ..
            } => source.memory_space != MemorySpaceAttr::Private,
            ProjectedBlockItemV1::Guarded(_) => true,
            ProjectedBlockItemV1::Pipeline(ProjectedPipelineEffectV1::Access { .. }) => true,
            ProjectedBlockItemV1::Pipeline(_) => false,
            ProjectedBlockItemV1::GeneratedFromSemanticTerminator(_) => false,
            ProjectedBlockItemV1::Effect { source: None, .. } => false,
        })
    }
}

/// Exact typed-root input for one ranked projection. Construction remains
/// crate-private and carries no artifact or launch authority.
pub(crate) struct ProductionRankedRootInputV1 {
    logical_name: String,
    kernel_binding: [u8; 32],
    source_launch: LaunchContract,
}

impl ProductionRankedRootInputV1 {
    pub(crate) fn new(
        logical_name: &str,
        kernel_binding: [u8; 32],
        source_launch: &LaunchContract,
    ) -> Self {
        Self {
            logical_name: logical_name.to_owned(),
            kernel_binding,
            source_launch: source_launch.clone(),
        }
    }
}

