    #[test]
    fn unknown_calls_memory_reads_and_private_addresses_remain_unresolved() {
        let unknown = call_discriminant_switch(0, vec![tensor_operand(1)]);
        let (switches, _, _) = deterministic_scalar_switch_projection(
            &[],
            &unknown,
            &vec![None; unknown.locals().len()],
            vec![],
            0,
        )
        .unwrap();
        assert!(switches[1].is_none());

        let loaded = deterministic_expression_switch(
            vec![scalar_assignment(
                4,
                SemanticRvalueKindV1::Load(SemanticMemoryLoadV1::new(
                    SemanticPlaceV1::new(SemanticLocalIdV1::from_index(1), vec![], SCALAR_TYPE)
                        .unwrap(),
                    SemanticVolatilityV1::NonVolatile,
                    None,
                )),
            )],
            deterministic_expression_locals(false),
            4,
        );
        let (switches, _, _) = deterministic_scalar_switch_projection(
            &[],
            &loaded,
            &vec![None; loaded.locals().len()],
            vec![],
            0,
        )
        .unwrap();
        assert!(switches[0].is_none());

        let pointer = SemanticLocalIdV1::from_index(3);
        let borrowed = deterministic_expression_switch(
            vec![
                statement(SemanticStatementKindV1::Assign(SemanticAssignmentV1::new(
                    SemanticPlaceV1::new(pointer, vec![], POINTER_TYPE).unwrap(),
                    SemanticRvalueV1::new(
                        POINTER_TYPE,
                        SemanticRvalueKindV1::Borrow {
                            kind: SemanticBorrowKindV1::Shared,
                            place: SemanticPlaceV1::new(
                                SemanticLocalIdV1::from_index(1),
                                vec![],
                                SCALAR_TYPE,
                            )
                            .unwrap(),
                        },
                    ),
                ))),
                scalar_assignment(
                    4,
                    SemanticRvalueKindV1::Cast {
                        kind: SemanticCastKindV1::PointerExposeProvenance,
                        operand: SemanticOperandV1::Copy(
                            SemanticPlaceV1::new(pointer, vec![], POINTER_TYPE).unwrap(),
                        ),
                    },
                ),
            ],
            vec![
                local(126, SCALAR_TYPE, SemanticLocalRoleV1::Return),
                local(127, SCALAR_TYPE, SemanticLocalRoleV1::Argument(0)),
                local(128, SCALAR_TYPE, SemanticLocalRoleV1::Temporary),
                local(129, POINTER_TYPE, SemanticLocalRoleV1::Temporary),
                local(130, SCALAR_TYPE, SemanticLocalRoleV1::Temporary),
                local(131, SCALAR_TYPE, SemanticLocalRoleV1::Temporary),
            ],
            4,
        );
        let (switches, _, _) = deterministic_scalar_switch_projection(
            &[],
            &borrowed,
            &vec![None; borrowed.locals().len()],
            vec![],
            0,
        )
        .unwrap();
        assert!(switches[0].is_none());

        let mut allocations = vec![None; borrowed.locals().len()];
        allocations[1] = Some(AllocationContractV1 {
            allocation_origin: 1,
            noalias_class: 1,
            writable: false,
            singleton_object: false,
        });
        let (switches, _, _) = deterministic_scalar_switch_projection_with_allocations(
            &[],
            &borrowed,
            &vec![None; borrowed.locals().len()],
            &allocations,
            vec![],
            0,
        )
        .unwrap();
        assert!(switches[0].is_some());
    }

    #[test]
    fn comparison_predicate_accepts_canonical_single_explicit_boolean_target() {
        let predicate = GuardPredicateV1 {
            comparisons: vec![(
                ProductionRankedValueV1::Argument(0),
                ProductionRankedValueV1::Argument(1),
            )],
        };
        for function in [
            single_explicit_boolean_switch(0, 2, 1),
            single_explicit_boolean_switch(1, 1, 2),
        ] {
            assert_eq!(
                projected_cfg_terminator(
                    &function,
                    0,
                    &[],
                    false,
                    &[],
                    &[None, Some(predicate.clone())],
                    &[],
                )
                .unwrap(),
                ProjectedCfgTerminatorV1::Predicate {
                    predicate: predicate.clone(),
                    true_block: 1,
                    false_block: 2,
                }
            );
        }
        assert!(matches!(
            projected_cfg_terminator(
                &single_explicit_boolean_switch(2, 1, 2),
                0,
                &[],
                false,
                &[],
                &[None, Some(predicate)],
                &[],
            ),
            Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a comparison predicate switch retained a non-boolean explicit value"
            ))
        ));
    }

    fn uniform_induction_function(bound_role: SemanticLocalRoleV1) -> SemanticFunctionDeclV1 {
        let induction = SemanticLocalIdV1::from_index(1);
        let predicate = SemanticLocalIdV1::from_index(2);
        let bound = SemanticLocalIdV1::from_index(3);
        let place = |local| SemanticPlaceV1::new(local, vec![], SCALAR_TYPE).unwrap();
        let operand = |local| SemanticOperandV1::Copy(place(local));
        let assign = |destination, value| {
            statement(SemanticStatementKindV1::Assign(SemanticAssignmentV1::new(
                place(destination),
                SemanticRvalueV1::new(SCALAR_TYPE, value),
            )))
        };
        projection_function_with_locals(
            vec![
                block(
                    100,
                    vec![assign(induction, SemanticRvalueKindV1::Use(constant(0)))],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(
                    101,
                    vec![assign(
                        predicate,
                        SemanticRvalueKindV1::Binary {
                            operation: SemanticBinaryOpV1::LessThan,
                            left: operand(induction),
                            right: operand(bound),
                        },
                    )],
                    SemanticTerminatorKindV1::SwitchInt {
                        discriminant: operand(predicate),
                        targets: SemanticSwitchTargetsV1::new(
                            vec![SemanticSwitchTargetV1::new(
                                0,
                                cfg_edge(SemanticEdgeRoleV1::SwitchValue, 3),
                            )],
                            cfg_edge(SemanticEdgeRoleV1::SwitchOtherwise, 2),
                        )
                        .unwrap(),
                    },
                ),
                block(
                    102,
                    vec![assign(
                        induction,
                        SemanticRvalueKindV1::Binary {
                            operation: SemanticBinaryOpV1::Add,
                            left: operand(induction),
                            right: constant(1),
                        },
                    )],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(103, vec![], SemanticTerminatorKindV1::Return),
            ],
            vec![
                local(100, SCALAR_TYPE, SemanticLocalRoleV1::Return),
                local(101, SCALAR_TYPE, SemanticLocalRoleV1::Temporary),
                local(102, SCALAR_TYPE, SemanticLocalRoleV1::Temporary),
                local(103, SCALAR_TYPE, bound_role),
            ],
        )
    }

    #[derive(Clone, Copy)]
    enum EscapedUniformAliasV1 {
        None,
        Induction,
        Comparison,
        Update,
    }

    fn escaped_uniform_induction_alias_function(
        escaped: EscapedUniformAliasV1,
    ) -> SemanticFunctionDeclV1 {
        let place = |local, ty| {
            SemanticPlaceV1::new(SemanticLocalIdV1::from_index(local), vec![], ty).unwrap()
        };
        let operand = |local, ty| SemanticOperandV1::Copy(place(local, ty));
        let assign = |destination, ty, value| {
            statement(SemanticStatementKindV1::Assign(SemanticAssignmentV1::new(
                place(destination, ty),
                SemanticRvalueV1::new(ty, value),
            )))
        };
        let borrow = |source| {
            assign(
                6,
                POINTER_TYPE,
                SemanticRvalueKindV1::Borrow {
                    kind: SemanticBorrowKindV1::Mutable,
                    place: place(source, SCALAR_TYPE),
                },
            )
        };
        let through_pointer = SemanticPlaceV1::new(
            SemanticLocalIdV1::from_index(6),
            vec![
                SemanticProjectionV1::new(SemanticProjectionKindV1::Dereference, SCALAR_TYPE)
                    .unwrap(),
            ],
            SCALAR_TYPE,
        )
        .unwrap();
        let indirect_write = || {
            statement(SemanticStatementKindV1::Store(SemanticMemoryStoreV1::new(
                through_pointer.clone(),
                constant(0),
                SemanticVolatilityV1::NonVolatile,
                None,
            )))
        };
        let mut entry = vec![assign(
            1,
            SCALAR_TYPE,
            SemanticRvalueKindV1::Use(constant(0)),
        )];
        if matches!(escaped, EscapedUniformAliasV1::Induction) {
            entry.push(borrow(1));
            entry.push(indirect_write());
        }
        let mut header = vec![assign(
            4,
            SCALAR_TYPE,
            SemanticRvalueKindV1::Use(operand(1, SCALAR_TYPE)),
        )];
        if matches!(escaped, EscapedUniformAliasV1::Comparison) {
            header.push(borrow(4));
            header.push(indirect_write());
        }
        header.push(assign(
            2,
            SCALAR_TYPE,
            SemanticRvalueKindV1::Binary {
                operation: SemanticBinaryOpV1::LessThan,
                left: operand(4, SCALAR_TYPE),
                right: operand(3, SCALAR_TYPE),
            },
        ));
        let mut latch = vec![assign(
            5,
            SCALAR_TYPE,
            SemanticRvalueKindV1::Use(operand(1, SCALAR_TYPE)),
        )];
        if matches!(escaped, EscapedUniformAliasV1::Update) {
            latch.push(borrow(5));
            latch.push(indirect_write());
        }
        latch.push(assign(
            1,
            SCALAR_TYPE,
            SemanticRvalueKindV1::Binary {
                operation: SemanticBinaryOpV1::Add,
                left: operand(5, SCALAR_TYPE),
                right: constant(1),
            },
        ));

        projection_function_with_locals(
            vec![
                block(
                    104,
                    entry,
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(
                    105,
                    header,
                    SemanticTerminatorKindV1::SwitchInt {
                        discriminant: operand(2, SCALAR_TYPE),
                        targets: SemanticSwitchTargetsV1::new(
                            vec![SemanticSwitchTargetV1::new(
                                0,
                                cfg_edge(SemanticEdgeRoleV1::SwitchValue, 4),
                            )],
                            cfg_edge(SemanticEdgeRoleV1::SwitchOtherwise, 2),
                        )
                        .unwrap(),
                    },
                ),
                block(
                    106,
                    vec![],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 3)),
                ),
                block(
                    107,
                    latch,
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(108, vec![], SemanticTerminatorKindV1::Return),
            ],
            vec![
                local(104, SCALAR_TYPE, SemanticLocalRoleV1::Return),
                local(105, SCALAR_TYPE, SemanticLocalRoleV1::Temporary),
                local(106, SCALAR_TYPE, SemanticLocalRoleV1::Temporary),
                local(107, SCALAR_TYPE, SemanticLocalRoleV1::Argument(0)),
                local(108, SCALAR_TYPE, SemanticLocalRoleV1::Temporary),
                local(109, SCALAR_TYPE, SemanticLocalRoleV1::Temporary),
                local(110, POINTER_TYPE, SemanticLocalRoleV1::Temporary),
            ],
        )
    }

    fn derived_uniform_induction_bound_function(
        widen_before_add: bool,
        escape_argument: bool,
    ) -> (SemanticFunctionDeclV1, Vec<SemanticTypeDeclV1>) {
        let wide_type = if widen_before_add {
            SemanticTypeIdV1::from_index(3)
        } else {
            SCALAR_TYPE
        };
        let wide_bytes = if widen_before_add { 8 } else { 4 };
        let induction = SemanticLocalIdV1::from_index(1);
        let predicate = SemanticLocalIdV1::from_index(2);
        let bound = SemanticLocalIdV1::from_index(3);
        let widened = SemanticLocalIdV1::from_index(4);
        let numerator = SemanticLocalIdV1::from_index(5);
        let argument = SemanticLocalIdV1::from_index(6);
        let escaped_pointer = SemanticLocalIdV1::from_index(7);
        let place = |local, ty| SemanticPlaceV1::new(local, vec![], ty).unwrap();
        let operand = |local, ty| SemanticOperandV1::Copy(place(local, ty));
        let wide_constant = |value| {
            SemanticOperandV1::Constant(SemanticConstantV1::new(
                wide_type,
                SemanticConstantValueV1::Scalar(
                    SemanticScalarValueV1::new(value, wide_bytes).unwrap(),
                ),
            ))
        };
        let assign = |destination, ty, value| {
            statement(SemanticStatementKindV1::Assign(SemanticAssignmentV1::new(
                place(destination, ty),
                SemanticRvalueV1::new(ty, value),
            )))
        };
        let mut entry_statements = Vec::new();
        if escape_argument {
            entry_statements.push(assign(
                escaped_pointer,
                POINTER_TYPE,
                SemanticRvalueKindV1::Borrow {
                    kind: SemanticBorrowKindV1::Mutable,
                    place: place(argument, SCALAR_TYPE),
                },
            ));
        }
        entry_statements.extend([
            assign(
                widened,
                wide_type,
                if widen_before_add {
                    SemanticRvalueKindV1::Cast {
                        kind: SemanticCastKindV1::Integer,
                        operand: operand(argument, SCALAR_TYPE),
                    }
                } else {
                    SemanticRvalueKindV1::Use(operand(argument, SCALAR_TYPE))
                },
            ),
            assign(
                numerator,
                wide_type,
                SemanticRvalueKindV1::Binary {
                    operation: SemanticBinaryOpV1::Add,
                    left: operand(widened, wide_type),
                    right: wide_constant(15),
                },
            ),
            assign(
                bound,
                wide_type,
                SemanticRvalueKindV1::Binary {
                    operation: SemanticBinaryOpV1::Divide,
                    left: operand(numerator, wide_type),
                    right: wide_constant(16),
                },
            ),
            assign(
                induction,
                wide_type,
                SemanticRvalueKindV1::Use(wide_constant(0)),
            ),
        ]);
        let function = projection_function_with_locals(
            vec![
                block(
                    104,
                    entry_statements,
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(
                    105,
                    vec![assign(
                        predicate,
                        SCALAR_TYPE,
                        SemanticRvalueKindV1::Binary {
                            operation: SemanticBinaryOpV1::LessThan,
                            left: operand(induction, wide_type),
                            right: operand(bound, wide_type),
                        },
                    )],
                    SemanticTerminatorKindV1::SwitchInt {
                        discriminant: operand(predicate, SCALAR_TYPE),
                        targets: SemanticSwitchTargetsV1::new(
                            vec![SemanticSwitchTargetV1::new(
                                0,
                                cfg_edge(SemanticEdgeRoleV1::SwitchValue, 3),
                            )],
                            cfg_edge(SemanticEdgeRoleV1::SwitchOtherwise, 2),
                        )
                        .unwrap(),
                    },
                ),
                block(
                    106,
                    vec![assign(
                        induction,
                        wide_type,
                        SemanticRvalueKindV1::Binary {
                            operation: SemanticBinaryOpV1::Add,
                            left: operand(induction, wide_type),
                            right: wide_constant(1),
                        },
                    )],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(107, vec![], SemanticTerminatorKindV1::Return),
            ],
            vec![
                local(104, SCALAR_TYPE, SemanticLocalRoleV1::Return),
                local(105, wide_type, SemanticLocalRoleV1::Temporary),
                local(106, SCALAR_TYPE, SemanticLocalRoleV1::Temporary),
                local(107, wide_type, SemanticLocalRoleV1::Temporary),
                local(108, wide_type, SemanticLocalRoleV1::Temporary),
                local(109, wide_type, SemanticLocalRoleV1::Temporary),
                local(110, SCALAR_TYPE, SemanticLocalRoleV1::Argument(0)),
                local(111, POINTER_TYPE, SemanticLocalRoleV1::Temporary),
            ],
        );
        let mut types = projection_types();
        types.push(SemanticTypeDeclV1::new(
            SemanticTypeIdentityV1::from_sha256(bytes(9)),
            SemanticLayoutIdentityV1::from_sha256(bytes(9)),
            SemanticTypeLayoutV1::new(Some(8), 8).unwrap(),
            SemanticTypeShapeV1::Scalar(SemanticScalarTypeV1::Integer {
                signed: false,
                bits: 64,
            }),
        ));
        (function, types)
    }

    #[derive(Clone, Copy)]
    enum CheckedBoundKind {
        Exact,
        MissingAssertion,
        StaleResultAssertion,
        WrongOperation,
        WrongSuccessRole,
        ExpectedOverflow,
        ReachableUnwind,
        NonDominatingAssertion,
        Overflowable,
        AddressEscaped,
        TupleAddressEscaped,
        MultipleDefinitions,
        NestedMissingAuthority,
        FloatCast,
        NarrowingCast,
        Multiply,
        Subtract,
    }

    fn checked_derived_uniform_induction_bound_function(
        kind: CheckedBoundKind,
    ) -> (SemanticFunctionDeclV1, Vec<SemanticTypeDeclV1>) {
        let induction = SemanticLocalIdV1::from_index(1);
        let predicate = SemanticLocalIdV1::from_index(2);
        let bound = SemanticLocalIdV1::from_index(3);
        let widened = SemanticLocalIdV1::from_index(4);
        let checked_result = SemanticLocalIdV1::from_index(5);
        let numerator = SemanticLocalIdV1::from_index(6);
        let argument = SemanticLocalIdV1::from_index(7);
        let escaped_pointer = SemanticLocalIdV1::from_index(8);
        let stale_result = SemanticLocalIdV1::from_index(9);
        let input_type = match kind {
            CheckedBoundKind::Overflowable => U64_TYPE,
            CheckedBoundKind::FloatCast => F64_TYPE,
            CheckedBoundKind::NarrowingCast => U128_TYPE,
            _ => SCALAR_TYPE,
        };
        let pointer_type = match kind {
            CheckedBoundKind::TupleAddressEscaped => CHECKED_U64_POINTER_TYPE,
            _ if input_type == U64_TYPE => U64_POINTER_TYPE,
            _ => POINTER_TYPE,
        };
        let place = |local, ty| SemanticPlaceV1::new(local, vec![], ty).unwrap();
        let operand = |local, ty| SemanticOperandV1::Copy(place(local, ty));
        let checked_field = |local, field, ty| {
            SemanticOperandV1::Move(
                SemanticPlaceV1::new(
                    local,
                    vec![
                        SemanticProjectionV1::new(SemanticProjectionKindV1::Field(field), ty)
                            .unwrap(),
                    ],
                    ty,
                )
                .unwrap(),
            )
        };
        let assign = |destination, ty, value| {
            statement(SemanticStatementKindV1::Assign(SemanticAssignmentV1::new(
                place(destination, ty),
                SemanticRvalueV1::new(ty, value),
            )))
        };
        let checked_operation = match kind {
            CheckedBoundKind::Multiply => SemanticCheckedBinaryOpV1::Multiply,
            CheckedBoundKind::Subtract => SemanticCheckedBinaryOpV1::Subtract,
            _ => SemanticCheckedBinaryOpV1::Add,
        };
        let checked_binary = |left, right| {
            SemanticRvalueKindV1::CheckedBinary(SemanticCheckedBinaryRvalueV1::new(
                checked_operation,
                left,
                typed_constant(U64_TYPE, right, 8),
            ))
        };
        let mut entry_statements = Vec::new();
        if matches!(kind, CheckedBoundKind::AddressEscaped) {
            entry_statements.push(assign(
                escaped_pointer,
                pointer_type,
                SemanticRvalueKindV1::Borrow {
                    kind: SemanticBorrowKindV1::Mutable,
                    place: place(argument, input_type),
                },
            ));
        }
        entry_statements.push(assign(
            widened,
            U64_TYPE,
            if matches!(kind, CheckedBoundKind::FloatCast) {
                SemanticRvalueKindV1::Cast {
                    kind: SemanticCastKindV1::Float,
                    operand: operand(argument, input_type),
                }
            } else if input_type != U64_TYPE {
                SemanticRvalueKindV1::Cast {
                    kind: SemanticCastKindV1::Integer,
                    operand: operand(argument, input_type),
                }
            } else {
                SemanticRvalueKindV1::Use(operand(argument, input_type))
            },
        ));
        let checked_right = if matches!(kind, CheckedBoundKind::Multiply) {
            1
        } else if matches!(kind, CheckedBoundKind::Subtract) {
            0
        } else {
            15
        };
        let nested_result = SemanticLocalIdV1::from_index(10);
        if matches!(kind, CheckedBoundKind::NestedMissingAuthority) {
            entry_statements.push(assign(
                nested_result,
                CHECKED_U64_TYPE,
                SemanticRvalueKindV1::CheckedBinary(SemanticCheckedBinaryRvalueV1::new(
                    SemanticCheckedBinaryOpV1::Add,
                    operand(widened, U64_TYPE),
                    typed_constant(U64_TYPE, 0, 8),
                )),
            ));
        }
        let checked_left = if matches!(kind, CheckedBoundKind::NestedMissingAuthority) {
            checked_field(nested_result, 0, U64_TYPE)
        } else {
            operand(widened, U64_TYPE)
        };
        entry_statements.push(assign(
            checked_result,
            CHECKED_U64_TYPE,
            checked_binary(checked_left.clone(), checked_right),
        ));
        if matches!(kind, CheckedBoundKind::MultipleDefinitions) {
            entry_statements.push(assign(
                checked_result,
                CHECKED_U64_TYPE,
                checked_binary(checked_left.clone(), checked_right),
            ));
        }
        if matches!(kind, CheckedBoundKind::TupleAddressEscaped) {
            entry_statements.push(assign(
                escaped_pointer,
                CHECKED_U64_POINTER_TYPE,
                SemanticRvalueKindV1::Borrow {
                    kind: SemanticBorrowKindV1::Mutable,
                    place: place(checked_result, CHECKED_U64_TYPE),
                },
            ));
        }
        if matches!(kind, CheckedBoundKind::StaleResultAssertion) {
            entry_statements.push(assign(
                stale_result,
                CHECKED_U64_TYPE,
                checked_binary(operand(widened, U64_TYPE), 16),
            ));
        }
        let asserted_result = if matches!(kind, CheckedBoundKind::StaleResultAssertion) {
            stale_result
        } else {
            checked_result
        };
        let asserted_right = if asserted_result == stale_result {
            16
        } else {
            checked_right
        };
        let exact_assertion = || SemanticTerminatorKindV1::Assert {
            condition: checked_field(asserted_result, 1, BOOL_TYPE),
            expected: matches!(kind, CheckedBoundKind::ExpectedOverflow),
            message: SemanticAssertMessageV1::Overflow {
                operation: match kind {
                    CheckedBoundKind::WrongOperation => SemanticBinaryOpV1::Subtract,
                    CheckedBoundKind::Multiply => SemanticBinaryOpV1::Multiply,
                    CheckedBoundKind::Subtract => SemanticBinaryOpV1::Subtract,
                    _ => SemanticBinaryOpV1::Add,
                },
                left: if asserted_result == stale_result {
                    operand(widened, U64_TYPE)
                } else {
                    checked_left.clone()
                },
                right: typed_constant(U64_TYPE, asserted_right, 8),
            },
            target: cfg_edge(
                if matches!(kind, CheckedBoundKind::WrongSuccessRole) {
                    SemanticEdgeRoleV1::Goto
                } else {
                    SemanticEdgeRoleV1::AssertSuccess
                },
                1,
            ),
            unwind: if matches!(kind, CheckedBoundKind::ReachableUnwind) {
                SemanticUnwindActionV1::Continue
            } else {
                SemanticUnwindActionV1::Unreachable
            },
        };
        let entry_terminator = if matches!(
            kind,
            CheckedBoundKind::MissingAssertion | CheckedBoundKind::NonDominatingAssertion
        ) {
            SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1))
        } else {
            exact_assertion()
        };
        let mut blocks = vec![
            block(104, entry_statements, entry_terminator),
            block(
                105,
                vec![
                    assign(
                        numerator,
                        U64_TYPE,
                        SemanticRvalueKindV1::Use(checked_field(checked_result, 0, U64_TYPE)),
                    ),
                    assign(
                        bound,
                        U64_TYPE,
                        SemanticRvalueKindV1::Binary {
                            operation: SemanticBinaryOpV1::Divide,
                            left: operand(numerator, U64_TYPE),
                            right: typed_constant(U64_TYPE, 16, 8),
                        },
                    ),
                    assign(
                        induction,
                        U64_TYPE,
                        SemanticRvalueKindV1::Use(typed_constant(U64_TYPE, 0, 8)),
                    ),
                ],
                SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 2)),
            ),
            block(
                106,
                vec![assign(
                    predicate,
                    SCALAR_TYPE,
                    SemanticRvalueKindV1::Binary {
                        operation: SemanticBinaryOpV1::LessThan,
                        left: operand(induction, U64_TYPE),
                        right: operand(bound, U64_TYPE),
                    },
                )],
                SemanticTerminatorKindV1::SwitchInt {
                    discriminant: operand(predicate, SCALAR_TYPE),
                    targets: SemanticSwitchTargetsV1::new(
                        vec![SemanticSwitchTargetV1::new(
                            0,
                            cfg_edge(SemanticEdgeRoleV1::SwitchValue, 4),
                        )],
                        cfg_edge(SemanticEdgeRoleV1::SwitchOtherwise, 3),
                    )
                    .unwrap(),
                },
            ),
            block(
                107,
                vec![assign(
                    induction,
                    U64_TYPE,
                    SemanticRvalueKindV1::Binary {
                        operation: SemanticBinaryOpV1::Add,
                        left: operand(induction, U64_TYPE),
                        right: typed_constant(U64_TYPE, 1, 8),
                    },
                )],
                SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 2)),
            ),
            block(108, vec![], SemanticTerminatorKindV1::Return),
        ];
        if matches!(kind, CheckedBoundKind::NonDominatingAssertion) {
            blocks.push(block(109, vec![], exact_assertion()));
        }
        let function = projection_function_with_locals(
            blocks,
            vec![
                local(104, U64_TYPE, SemanticLocalRoleV1::Return),
                local(105, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(106, SCALAR_TYPE, SemanticLocalRoleV1::Temporary),
                local(107, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(108, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(109, CHECKED_U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(110, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(111, input_type, SemanticLocalRoleV1::Argument(0)),
                local(112, pointer_type, SemanticLocalRoleV1::Temporary),
                local(113, CHECKED_U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(114, CHECKED_U64_TYPE, SemanticLocalRoleV1::Temporary),
            ],
        );
        (function, assertion_proof_types())
    }

    #[derive(Clone, Copy, Debug)]
    enum InductionCfgShape {
        Chain,
        HeaderCopyAlias,
        Branched,
        TwoLatches,
        ExtraExit,
        TrapSideExit,
        AnalysisSplit,
        IrreducibleEntry,
        MultiplePreheaders,
        ReusedComparisonLocal,
        MultipleHeaderComparisons,
    }

    fn multi_block_induction_function(
        shape: InductionCfgShape,
        bound_role: SemanticLocalRoleV1,
        step: u64,
    ) -> SemanticFunctionDeclV1 {
        multi_block_induction_function_with_operands(
            shape,
            bound_role,
            constant(0),
            constant(step.into()),
            false,
        )
    }

    fn multi_block_unchecked_induction_function(
        shape: InductionCfgShape,
        bound_role: SemanticLocalRoleV1,
        step: u64,
    ) -> SemanticFunctionDeclV1 {
        multi_block_induction_function_with_operands(
            shape,
            bound_role,
            constant(0),
            constant(step.into()),
            true,
        )
    }

    fn multi_block_induction_function_with_operands(
        shape: InductionCfgShape,
        bound_role: SemanticLocalRoleV1,
        initial_value: SemanticOperandV1,
        step_value: SemanticOperandV1,
        unchecked: bool,
    ) -> SemanticFunctionDeclV1 {
        let induction = SemanticLocalIdV1::from_index(1);
        let predicate = SemanticLocalIdV1::from_index(2);
        let bound = SemanticLocalIdV1::from_index(3);
        let body_predicate = SemanticLocalIdV1::from_index(4);
        let place = |local| SemanticPlaceV1::new(local, vec![], SCALAR_TYPE).unwrap();
        let operand = |local| SemanticOperandV1::Copy(place(local));
        let assign = |destination, value| {
            statement(SemanticStatementKindV1::Assign(SemanticAssignmentV1::new(
                place(destination),
                SemanticRvalueV1::new(SCALAR_TYPE, value),
            )))
        };
        let initialize = || assign(induction, SemanticRvalueKindV1::Use(initial_value.clone()));
        let compare = || {
            assign(
                predicate,
                SemanticRvalueKindV1::Binary {
                    operation: SemanticBinaryOpV1::LessThan,
                    left: operand(induction),
                    right: operand(bound),
                },
            )
        };
        let increment = || {
            assign(
                induction,
                if unchecked {
                    SemanticRvalueKindV1::UncheckedBinary(SemanticUncheckedBinaryRvalueV1::new(
                        SemanticUncheckedBinaryOpV1::Add,
                        operand(induction),
                        step_value.clone(),
                    ))
                } else {
                    SemanticRvalueKindV1::Binary {
                        operation: SemanticBinaryOpV1::Add,
                        left: operand(induction),
                        right: step_value.clone(),
                    }
                },
            )
        };
        let switch = |discriminant: SemanticOperandV1, false_target, true_target| {
            SemanticTerminatorKindV1::SwitchInt {
                discriminant,
                targets: SemanticSwitchTargetsV1::new(
                    vec![SemanticSwitchTargetV1::new(
                        0,
                        cfg_edge(SemanticEdgeRoleV1::SwitchValue, false_target),
                    )],
                    cfg_edge(SemanticEdgeRoleV1::SwitchOtherwise, true_target),
                )
                .unwrap(),
            }
        };
        let terminal_call = || {
            SemanticTerminatorKindV1::Call(
                SemanticDirectCallV1::new_callable(
                    SemanticCallableIdV1::from_index(0),
                    vec![],
                    None,
                    SemanticUnwindActionV1::Unreachable,
                )
                .unwrap(),
            )
        };
        let blocks = match shape {
            InductionCfgShape::Chain => vec![
                block(
                    110,
                    vec![initialize()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(111, vec![compare()], switch(operand(predicate), 5, 2)),
                block(
                    112,
                    vec![],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 3)),
                ),
                block(
                    113,
                    vec![],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 4)),
                ),
                block(
                    114,
                    vec![increment()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(115, vec![], SemanticTerminatorKindV1::Return),
            ],
            InductionCfgShape::HeaderCopyAlias => vec![
                block(
                    116,
                    vec![initialize()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(
                    117,
                    vec![
                        assign(
                            SemanticLocalIdV1::from_index(5),
                            SemanticRvalueKindV1::Use(operand(induction)),
                        ),
                        assign(
                            predicate,
                            SemanticRvalueKindV1::Binary {
                                operation: SemanticBinaryOpV1::LessThan,
                                left: operand(SemanticLocalIdV1::from_index(5)),
                                right: operand(bound),
                            },
                        ),
                    ],
                    switch(operand(predicate), 5, 2),
                ),
                block(
                    118,
                    vec![],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 3)),
                ),
                block(
                    119,
                    vec![],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 4)),
                ),
                block(
                    120,
                    vec![increment()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(121, vec![], SemanticTerminatorKindV1::Return),
            ],
            InductionCfgShape::Branched => vec![
                block(
                    120,
                    vec![initialize()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(121, vec![compare()], switch(operand(predicate), 6, 2)),
                block(122, vec![], switch(operand(body_predicate), 3, 4)),
                block(
                    123,
                    vec![],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 5)),
                ),
                block(
                    124,
                    vec![],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 5)),
                ),
                block(
                    125,
                    vec![increment()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(126, vec![], SemanticTerminatorKindV1::Return),
            ],
            InductionCfgShape::TwoLatches => vec![
                block(
                    130,
                    vec![initialize()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(131, vec![compare()], switch(operand(predicate), 5, 2)),
                block(132, vec![], switch(operand(body_predicate), 3, 4)),
                block(
                    133,
                    vec![increment()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(
                    134,
                    vec![],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(135, vec![], SemanticTerminatorKindV1::Return),
            ],
            InductionCfgShape::ExtraExit => vec![
                block(
                    140,
                    vec![initialize()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(141, vec![compare()], switch(operand(predicate), 4, 2)),
                block(142, vec![], switch(operand(body_predicate), 5, 3)),
                block(
                    143,
                    vec![increment()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(144, vec![], SemanticTerminatorKindV1::Return),
                block(145, vec![], SemanticTerminatorKindV1::Return),
            ],
            InductionCfgShape::TrapSideExit => vec![
                block(
                    195,
                    vec![initialize()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(196, vec![compare()], switch(operand(predicate), 4, 2)),
                block(197, vec![], switch(operand(body_predicate), 5, 3)),
                block(
                    198,
                    vec![increment()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(199, vec![], SemanticTerminatorKindV1::Return),
                block(
                    200,
                    vec![statement(SemanticStatementKindV1::StorageDead(
                        body_predicate,
                    ))],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 6)),
                ),
                block(201, vec![], terminal_call()),
            ],
            InductionCfgShape::AnalysisSplit => vec![
                block(
                    150,
                    vec![initialize()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(151, vec![compare()], switch(operand(predicate), 5, 2)),
                block(152, vec![], switch(operand(body_predicate), 3, 3)),
                block(
                    153,
                    vec![],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 4)),
                ),
                block(
                    154,
                    vec![increment()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(155, vec![], SemanticTerminatorKindV1::Return),
            ],
            InductionCfgShape::IrreducibleEntry => vec![
                block(160, vec![], switch(operand(body_predicate), 1, 3)),
                block(
                    161,
                    vec![initialize()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 2)),
                ),
                block(162, vec![compare()], switch(operand(predicate), 5, 3)),
                block(
                    163,
                    vec![],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 4)),
                ),
                block(
                    164,
                    vec![increment()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 2)),
                ),
                block(165, vec![], SemanticTerminatorKindV1::Return),
            ],
            InductionCfgShape::MultiplePreheaders => vec![
                block(170, vec![], switch(operand(body_predicate), 1, 2)),
                block(
                    171,
                    vec![initialize()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 3)),
                ),
                block(
                    172,
                    vec![],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 3)),
                ),
                block(173, vec![compare()], switch(operand(predicate), 6, 4)),
                block(
                    174,
                    vec![],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 5)),
                ),
                block(
                    175,
                    vec![increment()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 3)),
                ),
                block(176, vec![], SemanticTerminatorKindV1::Return),
            ],
            InductionCfgShape::ReusedComparisonLocal => vec![
                block(
                    180,
                    vec![
                        initialize(),
                        assign(predicate, SemanticRvalueKindV1::Use(constant(0))),
                    ],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(181, vec![compare()], switch(operand(predicate), 4, 2)),
                block(
                    182,
                    vec![],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 3)),
                ),
                block(
                    183,
                    vec![increment()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(184, vec![], SemanticTerminatorKindV1::Return),
            ],
            InductionCfgShape::MultipleHeaderComparisons => vec![
                block(
                    190,
                    vec![initialize()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(
                    191,
                    vec![compare(), compare()],
                    switch(operand(predicate), 4, 2),
                ),
                block(
                    192,
                    vec![],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 3)),
                ),
                block(
                    193,
                    vec![increment()],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(194, vec![], SemanticTerminatorKindV1::Return),
            ],
        };
        projection_function_with_locals(
            blocks,
            vec![
                local(100, SCALAR_TYPE, SemanticLocalRoleV1::Return),
                local(101, SCALAR_TYPE, SemanticLocalRoleV1::Temporary),
                local(102, SCALAR_TYPE, SemanticLocalRoleV1::Temporary),
                local(103, SCALAR_TYPE, bound_role),
                local(104, SCALAR_TYPE, SemanticLocalRoleV1::Argument(1)),
                local(105, SCALAR_TYPE, SemanticLocalRoleV1::Temporary),
            ],
        )
    }

    #[derive(Clone, Copy)]
    enum WidenedLatchKind {
        Ordinary,
        Unchecked,
        Checked,
        CheckedWrongMessage,
        CheckedExpectedOverflow,
        CheckedReachableUnwind,
    }

    fn widened_u64_induction_function(step: u64) -> SemanticFunctionDeclV1 {
        widened_u64_induction_function_with_latch(step, WidenedLatchKind::Ordinary)
    }

    fn widened_u64_induction_function_with_latch(
        step: u64,
        latch_kind: WidenedLatchKind,
    ) -> SemanticFunctionDeclV1 {
        let induction = SemanticLocalIdV1::from_index(1);
        let predicate = SemanticLocalIdV1::from_index(2);
        let bound = SemanticLocalIdV1::from_index(3);
        let narrow_bound = SemanticLocalIdV1::from_index(4);
        let checked_result = SemanticLocalIdV1::from_index(5);
        let checked_alias = SemanticLocalIdV1::from_index(6);
        let u64_place = |local| SemanticPlaceV1::new(local, vec![], U64_TYPE).unwrap();
        let u32_place = |local| SemanticPlaceV1::new(local, vec![], SCALAR_TYPE).unwrap();
        let u64_operand = |local| SemanticOperandV1::Copy(u64_place(local));
        let u32_operand = |local| SemanticOperandV1::Copy(u32_place(local));
        let checked_field = |field, ty| {
            SemanticOperandV1::Move(
                SemanticPlaceV1::new(
                    checked_result,
                    vec![
                        SemanticProjectionV1::new(SemanticProjectionKindV1::Field(field), ty)
                            .unwrap(),
                    ],
                    ty,
                )
                .unwrap(),
            )
        };
        let assign = |destination: SemanticPlaceV1,
                      result_type: SemanticTypeIdV1,
                      value: SemanticRvalueKindV1| {
            statement(SemanticStatementKindV1::Assign(SemanticAssignmentV1::new(
                destination,
                SemanticRvalueV1::new(result_type, value),
            )))
        };
        let switch = SemanticTerminatorKindV1::SwitchInt {
            discriminant: u32_operand(predicate),
            targets: SemanticSwitchTargetsV1::new(
                vec![SemanticSwitchTargetV1::new(
                    0,
                    cfg_edge(SemanticEdgeRoleV1::SwitchValue, 5),
                )],
                cfg_edge(SemanticEdgeRoleV1::SwitchOtherwise, 2),
            )
            .unwrap(),
        };
        let step_operand = || typed_constant(U64_TYPE, u128::from(step), 8);
        let (producer_statements, producer_terminator, latch_statements) = match latch_kind {
            WidenedLatchKind::Ordinary => (
                vec![],
                SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 4)),
                vec![assign(
                    u64_place(induction),
                    U64_TYPE,
                    SemanticRvalueKindV1::Binary {
                        operation: SemanticBinaryOpV1::Add,
                        left: u64_operand(induction),
                        right: step_operand(),
                    },
                )],
            ),
            WidenedLatchKind::Unchecked => (
                vec![],
                SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 4)),
                vec![assign(
                    u64_place(induction),
                    U64_TYPE,
                    SemanticRvalueKindV1::UncheckedBinary(SemanticUncheckedBinaryRvalueV1::new(
                        SemanticUncheckedBinaryOpV1::Add,
                        u64_operand(induction),
                        step_operand(),
                    )),
                )],
            ),
            WidenedLatchKind::Checked
            | WidenedLatchKind::CheckedWrongMessage
            | WidenedLatchKind::CheckedExpectedOverflow
            | WidenedLatchKind::CheckedReachableUnwind => {
                let checked_left = u64_operand(checked_alias);
                let checked_right = step_operand();
                (
                    vec![
                        assign(
                            u64_place(checked_alias),
                            U64_TYPE,
                            SemanticRvalueKindV1::Use(u64_operand(induction)),
                        ),
                        assign(
                            SemanticPlaceV1::new(checked_result, vec![], CHECKED_U64_TYPE).unwrap(),
                            CHECKED_U64_TYPE,
                            SemanticRvalueKindV1::CheckedBinary(
                                SemanticCheckedBinaryRvalueV1::new(
                                    SemanticCheckedBinaryOpV1::Add,
                                    checked_left.clone(),
                                    checked_right.clone(),
                                ),
                            ),
                        ),
                    ],
                    SemanticTerminatorKindV1::Assert {
                        condition: checked_field(1, BOOL_TYPE),
                        expected: matches!(latch_kind, WidenedLatchKind::CheckedExpectedOverflow),
                        message: SemanticAssertMessageV1::Overflow {
                            operation: if matches!(
                                latch_kind,
                                WidenedLatchKind::CheckedWrongMessage
                            ) {
                                SemanticBinaryOpV1::Subtract
                            } else {
                                SemanticBinaryOpV1::Add
                            },
                            left: SemanticOperandV1::Move(u64_place(checked_alias)),
                            right: checked_right,
                        },
                        target: cfg_edge(SemanticEdgeRoleV1::AssertSuccess, 4),
                        unwind: if matches!(latch_kind, WidenedLatchKind::CheckedReachableUnwind) {
                            SemanticUnwindActionV1::Continue
                        } else {
                            SemanticUnwindActionV1::Unreachable
                        },
                    },
                    vec![assign(
                        u64_place(induction),
                        U64_TYPE,
                        SemanticRvalueKindV1::Use(checked_field(0, U64_TYPE)),
                    )],
                )
            }
        };
        projection_function_with_locals(
            vec![
                block(
                    210,
                    vec![
                        assign(
                            u64_place(induction),
                            U64_TYPE,
                            SemanticRvalueKindV1::Use(typed_constant(U64_TYPE, 0, 8)),
                        ),
                        assign(
                            u64_place(bound),
                            U64_TYPE,
                            SemanticRvalueKindV1::Cast {
                                kind: SemanticCastKindV1::Integer,
                                operand: u32_operand(narrow_bound),
                            },
                        ),
                    ],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(
                    211,
                    vec![assign(
                        u32_place(predicate),
                        SCALAR_TYPE,
                        SemanticRvalueKindV1::Binary {
                            operation: SemanticBinaryOpV1::LessThan,
                            left: u64_operand(induction),
                            right: u64_operand(bound),
                        },
                    )],
                    switch,
                ),
                block(
                    212,
                    vec![],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 3)),
                ),
                block(213, producer_statements, producer_terminator),
                block(
                    214,
                    latch_statements,
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(215, vec![], SemanticTerminatorKindV1::Return),
            ],
            vec![
                local(210, U64_TYPE, SemanticLocalRoleV1::Return),
                local(211, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(212, SCALAR_TYPE, SemanticLocalRoleV1::Temporary),
                local(213, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(214, SCALAR_TYPE, SemanticLocalRoleV1::Argument(0)),
                local(215, CHECKED_U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(216, U64_TYPE, SemanticLocalRoleV1::Temporary),
            ],
        )
    }

    fn project_test_inductions(
        function: &SemanticFunctionDeclV1,
    ) -> Result<
        (
            Vec<ProjectedUniformInductionV1>,
            Vec<ProductionRankedOperationV1>,
            usize,
        ),
        ProductionRankedProjectionErrorV1,
    > {
        let types = projection_types();
        project_test_inductions_with_types(&types, function)
    }

    fn project_test_inductions_with_types(
        types: &[SemanticTypeDeclV1],
        function: &SemanticFunctionDeclV1,
    ) -> Result<
        (
            Vec<ProjectedUniformInductionV1>,
            Vec<ProductionRankedOperationV1>,
            usize,
        ),
        ProductionRankedProjectionErrorV1,
    > {
        project_test_inductions_with_types_and_callables(types, &[], function)
    }

    fn project_test_inductions_with_types_and_callables(
        types: &[SemanticTypeDeclV1],
        callables: &[SemanticCallableDeclV1],
        function: &SemanticFunctionDeclV1,
    ) -> Result<
        (
            Vec<ProjectedUniformInductionV1>,
            Vec<ProductionRankedOperationV1>,
            usize,
        ),
        ProductionRankedProjectionErrorV1,
    > {
        let constants = constant_locals(function)?;
        let origins = local_stable_argument_origins(types, function).unwrap();
        let definitions = local_definition_counts(function);
        let mut arguments = vec![None; function.locals().len()];
        let mut next_argument = 1;
        let mut operations = Vec::new();
        let mut next_value = 0;
        let mut inductions = project_uniform_inductions_v1(
            callables,
            types,
            function,
            &constants,
            &origins,
            &definitions,
            &mut arguments,
            &mut next_argument,
            &mut operations,
            &mut next_value,
        )?;
        reconcile_source_progress_and_emit_unsigned_casts_v1(
            types,
            function,
            &constants,
            &origins,
            &definitions,
            &arguments,
            &mut inductions,
            &mut operations,
            &mut next_value,
        )?;
        Ok((inductions, operations, next_argument))
    }

    fn assert_incomplete<T>(
        result: Result<T, ProductionRankedProjectionErrorV1>,
        expected: &'static str,
    ) {
        match result {
            Err(ProductionRankedProjectionErrorV1::Incomplete(actual)) => {
                assert_eq!(actual, expected);
            }
            Err(other) => panic!("expected incomplete projection, got {other}"),
            Ok(_) => panic!("expected incomplete projection"),
        }
    }

    fn assert_loop_unsupported<T>(
        result: Result<T, ProductionRankedProjectionErrorV1>,
        expected: &'static str,
    ) {
        match result {
            Err(ProductionRankedProjectionErrorV1::Unsupported(actual)) => {
                assert_eq!(actual, expected);
            }
            Err(other) => panic!("expected unsupported projection, got {other}"),
            Ok(_) => panic!("expected unsupported projection"),
        }
    }

    #[test]
    fn dynamic_parameter_induction_projects_to_legal_ranked_ssa_edges() {
        let function = uniform_induction_function(SemanticLocalRoleV1::Argument(0));
        let constants = constant_locals(&function).unwrap();
        let origins = local_stable_argument_origins(&projection_types(), &function).unwrap();
        let definitions = local_definition_counts(&function);
        let mut arguments = vec![None; function.locals().len()];
        let mut next_argument = 1;
        let mut entry_operations = Vec::new();
        let mut next_value = 0;
        let inductions = project_uniform_inductions_v1(
            &[],
            &projection_types(),
            &function,
            &constants,
            &origins,
            &definitions,
            &mut arguments,
            &mut next_argument,
            &mut entry_operations,
            &mut next_value,
        )
        .unwrap();
        assert_eq!(inductions.len(), 1);

        let (blocks, _, _) = build_ranked_cfg(
            &projection_types(),
            &function,
            &[],
            &vec![None; function.locals().len()],
            &vec![None; function.blocks().len()],
            &inductions,
            entry_operations,
            (0..function.blocks().len())
                .map(|_| ProjectedSemanticBlockV1 { items: vec![] })
                .collect(),
        )
        .unwrap();
        assert_eq!(blocks[2].index_argument_count(), 1);
        assert_eq!(blocks[3].index_argument_count(), 1);
        assert!(matches!(
            blocks[2].terminator(),
            ProductionRankedTerminatorV1::IndexLessThanArgs { .. }
        ));
        assert!(matches!(
            blocks[3].terminator(),
            ProductionRankedTerminatorV1::BranchArgsAddAt { .. }
        ));
        ProductionRankedKernelV1::new("uniform_dynamic_loop", next_argument, blocks).unwrap();
    }

    #[test]
    fn unsigned_cast_width_is_closed_to_exact_unsigned_type_maxima() {
        assert_eq!(unsigned_bit_width_for_maximum_v1(u8::MAX.into()), Some(8));
        assert_eq!(unsigned_bit_width_for_maximum_v1(u16::MAX.into()), Some(16));
        assert_eq!(unsigned_bit_width_for_maximum_v1(u32::MAX.into()), Some(32));
        assert_eq!(unsigned_bit_width_for_maximum_v1(u64::MAX.into()), Some(64));
        assert_eq!(unsigned_bit_width_for_maximum_v1(0), None);
        assert_eq!(unsigned_bit_width_for_maximum_v1(100), None);
        assert_eq!(unsigned_bit_width_for_maximum_v1(u128::MAX), None);
    }

    #[test]
    fn source_induction_width_rejects_u32_wrap_and_accepts_a_widened_u64_recurrence() {
        let wrapping = multi_block_induction_function(
            InductionCfgShape::Chain,
            SemanticLocalRoleV1::Argument(0),
            16,
        );
        assert_incomplete(
            project_test_inductions(&wrapping),
            "a compiler-derived source induction update may overflow its exact unsigned type",
        );

        let types = assertion_proof_types();
        let widened = widened_u64_induction_function(16);
        let (inductions, operations, _) =
            project_test_inductions_with_types(&types, &widened).unwrap();
        assert_eq!(inductions[0].source_progress.induction_type, U64_TYPE);
        assert_eq!(inductions[0].source_progress.step_value, 16);
        assert!(matches!(
            operations.last(),
            Some(ProductionRankedOperationV1::IndexUnsignedCast { bit_width: 32, .. })
        ));

        let unchecked = widened_u64_induction_function_with_latch(16, WidenedLatchKind::Unchecked);
        let (inductions, _, _) = project_test_inductions_with_types(&types, &unchecked).unwrap();
        assert_eq!(
            inductions[0].source_progress.update,
            ProjectedSourceInductionUpdateV1::Unchecked
        );

        let unchecked_wrapping = multi_block_unchecked_induction_function(
            InductionCfgShape::Chain,
            SemanticLocalRoleV1::Argument(0),
            16,
        );
        assert_incomplete(
            project_test_inductions(&unchecked_wrapping),
            "a compiler-derived source induction update may overflow its exact unsigned type",
        );
    }

